"""Self-contained Review/final-acceptance workbench."""
WORKBENCH_HTML=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Circle Control Desk</title><style>
@media(max-width:760px){body header{height:auto;min-height:76px;padding:12px 16px;gap:12px}body header h1{font-size:18px;line-height:1.15}body main{min-height:0}}
:root{--ink:#07131f;--panel:#102333;--line:#294557;--paper:#eaf1f2;--muted:#8ea6b2;--cyan:#3dd6c6;--amber:#ffbb55;--red:#ff6b6b}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font:14px/1.5 ui-monospace,Consolas,monospace}header{height:68px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px}h1,h2,h3{font-family:system-ui;margin-top:0}small,.muted{color:var(--muted)}button,input,textarea,select{font:inherit}button{background:var(--cyan);color:#031412;border:0;padding:10px 14px;font-weight:700;cursor:pointer}.secondary{background:#244357;color:var(--paper)}main{display:grid;grid-template-columns:minmax(280px,34%) 1fr;min-height:calc(100vh - 68px)}#tasks{border-right:1px solid var(--line);padding:20px}.task{position:relative;border:1px solid var(--line);background:var(--panel);padding:14px 16px 14px 24px;margin-bottom:10px;cursor:pointer}.task:before{content:"";position:absolute;left:8px;top:12px;bottom:12px;width:3px;background:var(--cyan)}.task[data-state=cancelled]:before{background:var(--red)}.task[data-state=review]:before,.task[data-state=approved]:before{background:var(--amber)}.task strong{display:block;font-family:system-ui}.meta{display:flex;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin-top:7px}#detail{padding:28px;overflow:auto}section{border-top:1px solid var(--line);padding:18px 0}.criterion{padding:10px 12px;border-left:3px solid var(--line);background:#0b1d2a;margin:8px 0}.evidence{font-size:12px;color:#b8ccd3;overflow-wrap:anywhere}form,label{display:grid;gap:9px}form{max-width:700px}textarea,input,select{width:100%;padding:10px;background:#07131f;color:var(--paper);border:1px solid var(--line)}#login{max-width:400px;margin:12vh auto;background:var(--panel);padding:28px;border:1px solid var(--line)}.error{color:var(--red)}@media(max-width:760px){header{padding:0 16px}main{display:block}#tasks{border-right:0;border-bottom:1px solid var(--line);max-height:42vh;overflow:auto}#detail{padding:18px}button{min-height:44px}}
</style></head><body><div id="login"><h1>Circle Control Desk</h1><p class="muted">个人令牌只用于换取 HttpOnly 会话。</p><form id="loginForm"><label>令牌<input id="token" type="password" required></label><button>进入</button><div id="loginError" class="error"></div></form></div><div id="app" hidden><header><div><h1>Circle / Control Desk</h1><small id="identity"></small></div><button class="secondary" onclick="logout()">退出</button></header><main><aside id="tasks"></aside><article id="detail"><p class="muted">选择任务查看详情。</p></article></main></div><script>
let me,tasksData=[],active;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){let r=await fetch(p,{...o,headers:{'Content-Type':'application/json'}}),b=await r.json().catch(()=>({error:r.statusText}));if(!r.ok)throw Error(b.error);return b}async function boot(){try{me=await api('/v1/me');login.hidden=true;app.hidden=false;identity.textContent=me.identity+' · '+me.roles.join(' / ');await load()}catch(e){}}async function load(){tasksData=await api('/v1/tasks');tasks.innerHTML='<h2>任务流</h2>'+tasksData.map(t=>`<div class="task" data-state="${t.state}" onclick="openTask('${t.id}')"><strong>${esc(t.source.title)}</strong><div class="meta"><span>${t.id}</span><span>${t.state}</span><span>尝试 ${t.attempt}</span><span>${esc(t.owner||'未认领')}</span></div></div>`).join('');if(active){active=tasksData.find(t=>t.id===active.id);render()}}function openTask(id){active=tasksData.find(t=>t.id===id);render()}function verdicts(){return active.source.acceptance.map((c,i)=>`<div class="criterion"><b>${i+1}. ${esc(c.text)}</b><label>结论<select name="status"><option>pass</option><option>fail</option></select></label><label>说明<input name="vnote" required></label></div>`).join('')}function actions(t){let a=[];if(me.roles.includes('reviewer')&&t.state==='review'&&t.reviewer===me.identity)a.push('review');if(me.roles.includes('admin')){a.push('assign');if(t.state==='approved')a.push('accept');if(t.state!=='done')a.push('cancel','recover');if(['cancelled','review','approved'].includes(t.state))a.push('retry')}return a.length?a:['read-only']}function render(){let t=active,req=Object.values(t.requirements||{}).filter(Boolean)[0],ev=t.submission?.evidence||[];detail.innerHTML=`<h2>${esc(t.source.title)}</h2><div class="meta"><span>${t.id}</span><span>${t.state}</span><span>版本 ${t.version}</span><span>负责人 ${esc(t.owner||'—')}</span><span>审核人 ${esc(t.reviewer||'—')}</span></div><section><h3>需求</h3><p>${esc(req?.content||'未关联')}</p><small>${esc(req?.source_channel||'')} ${esc(req?.source_locator||'')}</small></section><section><h3>Issue 定义</h3><p><b>Goal</b><br>${esc(t.source.goal)}</p><p><b>Expected</b><br>${esc(t.source.expected_behavior)}</p><p><b>Boundaries</b><br>${esc(t.source.boundaries)}</p></section><section><h3>验收项与证据</h3>${t.source.acceptance.map((c,i)=>`<div class="criterion"><b>${i+1}. ${esc(c.text)}</b>${ev.filter(e=>e.criterion===i+1).map(e=>`<div class="evidence">${esc(e.kind)} · ${esc(e.locator)} · ${esc(e.sha256)}</div>`).join('')}</div>`).join('')}<p>提交: ${esc(t.submission?.commit||'—')}</p><p>依赖提交: ${esc(JSON.stringify(t.dependency_commits||{}))}</p></section><section><h3>操作</h3><form id="actionForm"><label>操作<select name="action" onchange="fields()">${actions(t).map(a=>`<option>${a}</option>`).join('')}</select></label><div id="actionFields"></div><button>提交决定</button><div id="actionError" class="error"></div></form></section><section><h3>历史</h3>${(t.history||[]).slice().reverse().map(h=>`<p><b>${h.action}</b> · ${esc(h.actor)} · ${esc(h.at)}</p>`).join('')}</section>`;actionForm.onsubmit=submit;fields()}function fields(){let a=actionForm.action.value,f=a==='assign'?'<label>审核人<input name="reviewer" required></label>':'';if(['review','accept'].includes(a))f+=(a==='review'?'<label>决定<select name="decision"><option>approve</option><option>reject</option></select></label>':'')+verdicts();if(!['read-only','assign'].includes(a))f+='<label>说明<textarea name="note" required></textarea></label>';actionFields.innerHTML=f}async function submit(e){e.preventDefault();let f=new FormData(e.target),a=f.get('action');if(a==='read-only')return;let b={expected_version:active.version};if(a==='assign')b.reviewer=f.get('reviewer');else{b.note=f.get('note');if(a==='review')b.decision=f.get('decision');if(['review','accept'].includes(a))b.verdicts=[...e.target.querySelectorAll('[name=status]')].map((x,i)=>({criterion:i+1,status:x.value,note:[...e.target.querySelectorAll('[name=vnote]')][i].value}))}try{active=await api('/v1/tasks/'+active.id+'/'+a,{method:'POST',body:JSON.stringify(b)});await load()}catch(x){actionError.textContent=x.message}}loginForm.onsubmit=async e=>{e.preventDefault();try{await api('/v1/session',{method:'POST',body:JSON.stringify({token:token.value})});token.value='';await boot()}catch(x){loginError.textContent=x.message}};async function logout(){await api('/v1/session',{method:'DELETE'});location.reload()}boot();
</script></body></html>'''
# Keep the generated page self-contained while making admin rejection/recovery
# actions send the same reason field as the JSON API.
WORKBENCH_HTML = WORKBENCH_HTML.replace(
    "if(t.state==='approved')a.push('accept');",
    "if(t.state==='approved')a.push('accept','reject');",
).replace(
    "else{b.note=f.get('note');if(a==='review')",
    "else{if(['cancel','recover','retry','reject'].includes(a))b.reason=f.get('note');else b.note=f.get('note');if(a==='review')",
)
